#include <stdio.h>
#include <stdlib.h>

__attribute__((noinline)) static int read_after_free(volatile int *value) {
    return *value;
}

int main(void) {
    int *value = malloc(sizeof(*value));
    if (!value) return 2;
    *value = 73;
    free(value);
    printf("read-after-free=%d\n", read_after_free(value));
    return 0;
}

#include <pthread.h>
#include <stdio.h>

static volatile int shared;
static void *racing_write(void *unused) {
    (void)unused;
    for (int i = 0; i < 100000; i++) shared++;
    return NULL;
}

int main(void) {
    pthread_t first, second;
    if (pthread_create(&first, NULL, racing_write, NULL)) return 2;
    if (pthread_create(&second, NULL, racing_write, NULL)) return 3;
    pthread_join(first, NULL);
    pthread_join(second, NULL);
    printf("shared=%d\n", shared);
    return 0;
}

#include <limits.h>
#include <stdio.h>

int main(void) {
    volatile int maximum = INT_MAX;
    volatile int one = 1;
    printf("overflow=%d\n", maximum + one);
    return 0;
}
